/// authorization to change the fixed laugh action.
enum FixedLaughFaceIdentity {
    static let revision = 1.0
    static let riderClosure = 0.40
    static let friendClosure = 0.28
    static let mouthHalfWidth = 14.5
    static let mouthDepth = 11.6
    static let mouthBeatCenter = 0.94
    static let mouthBeatAmplitude = 0.06
    static let mouthBeatFrequency = 13.0
    static let friendBrowTension = 2.8
    static let sweatOpacity = 0.52
    static let sweatDropCount = 2
}

